// ─── IDEMPOTENCY CHECK ───────────────────────────────────────────
// Validate all required fields and generate a deduplication key
// based on author_id + current UTC date (day-level granularity)
const body = $json.body || $json;
const authorId = body.author_id;
const triggeredAt = body.triggered_at || new Date().toISOString();
const logId = body.log_id || null;

if (!authorId) {
  throw new Error('Missing required field: author_id');
}

// Build dedup key: same author, same calendar day => same key
const today = new Date().toISOString().split('T')[0];
const dedupKey = `${authorId}::${today}`;

return [{
  json: {
    author_id: authorId,
    log_id: logId,
    triggered_at: triggeredAt,
    dedup_key: dedupKey,
    bubble_base_url: body.bubble_base_url || 'https://YOUR-APP.bubbleapps.io/api/1.1/obj',
    bubble_api_key: body.bubble_api_key || ''
  }
}];

// ─── AGGREGATE & ENRICH DATA ─────────────────────────────────────
const authorData = $('Fetch Author Data from Bubble').item.json.response || {};
const booksData = ($('Fetch Author Books from Bubble').item.json.response?.results) || [];

// Compute consolidated totals
let totalEarned = 0, totalPaid = 0, totalPending = 0;
const publishedBooks = [];
const productionBooks = [];

booksData.forEach(book => {
  totalEarned += (book.total_royalty_earned || 0);
  totalPaid += (book.royalty_paid || 0);
  totalPending += (book.royalty_pending || 0);

  if (book.status && book.status.toLowerCase().includes('published')) {
    publishedBooks.push(book);
  } else {
    productionBooks.push(book);
  }
});

// Determine payout status label
let overallStatus = 'Fully Paid';
if (totalPending > 0) {
  // Check if any pending book has last_payout_date > 90 days ago or no payout at all
  const now = new Date();
  const isOverdue = publishedBooks.some(b => {
    if (b.royalty_pending > 0) {
      if (!b.last_royalty_payout_date) return true; // never paid
      const last = new Date(b.last_royalty_payout_date);
      const diffDays = (now - last) / (1000 * 60 * 60 * 24);
      return diffDays > 90;
    }
    return false;
  });
  overallStatus = isOverdue ? 'Overdue' : 'Pending';
}

// Compute next expected payout quarter
const now = new Date();
const month = now.getMonth(); // 0-indexed
let nextPayoutQuarter;
if (month < 3)      nextPayoutQuarter = 'Q1 (March 31 + 45 days = ~May 15)';
else if (month < 6) nextPayoutQuarter = 'Q2 (June 30 + 45 days = ~Aug 14)';
else if (month < 9) nextPayoutQuarter = 'Q3 (September 30 + 45 days = ~Nov 14)';
else                nextPayoutQuarter = 'Q4 (December 31 + 45 days = ~Feb 14)';

return [{
  json: {
    author: {
      id: authorData._id || $('Validate & Extract Input').item.json.author_id,
      name: authorData.name || 'Author',
      email: authorData.email || '',
      city: authorData.city || ''
    },
    summary: {
      total_earned: totalEarned,
      total_paid: totalPaid,
      total_pending: totalPending,
      overall_status: overallStatus,
      books_published: publishedBooks.length,
      books_in_production: productionBooks.length,
      next_payout_quarter: nextPayoutQuarter
    },
    published_books: publishedBooks,
    production_books: productionBooks,
    log_id: $('Validate & Extract Input').item.json.log_id,
    bubble_base_url: $('Validate & Extract Input').item.json.bubble_base_url,
    bubble_api_key: $('Validate & Extract Input').item.json.bubble_api_key
  }
}];

// ─── BUILD AI PROMPT ──────────────────────────────────────────────
const d = $json;
const a = d.author;
const s = d.summary;

// Format currency helper
const fmt = n => `₹${Number(n).toLocaleString('en-IN')}`;

// Build per-book section for published books
let bookDetails = '';
d.published_books.forEach((b, i) => {
  const statusBadge = b.royalty_pending === 0 ? '✅ Fully Paid'
    : (!b.last_royalty_payout_date) ? '🔴 Never Paid'
    : '🟡 Payment Pending';

  bookDetails += `
${i + 1}. "${b.title}" (${b.genre || 'General'})
   - ISBN: ${b.isbn || 'N/A'}
   - Published: ${b.publication_date ? new Date(b.publication_date).toDateString() : 'N/A'}
   - MRP: ${b.mrp ? fmt(b.mrp) : 'N/A'} | Royalty per copy: ${b.author_royalty_per_copy ? fmt(b.author_royalty_per_copy) : 'N/A'}
   - Total copies sold: ${b.total_copies_sold || 0}
   - Total royalty earned: ${fmt(b.total_royalty_earned || 0)}
   - Royalty paid to date: ${fmt(b.royalty_paid || 0)}
   - Royalty pending: ${fmt(b.royalty_pending || 0)}
   - Last payout date: ${b.last_royalty_payout_date ? new Date(b.last_royalty_payout_date).toDateString() : 'No payout yet'}
   - Status: ${statusBadge}
   - Available on: ${(b.available_on || []).join(', ') || 'N/A'}
`;
});

// Build production books section
let productionDetails = '';
if (d.production_books.length > 0) {
  d.production_books.forEach((b, i) => {
    productionDetails += `\n${i + 1}. "${b.title}" — Current stage: ${b.status}`;
  });
}

const systemPrompt = `You are a warm, professional communication specialist for BookLeaf Publishing — a boutique self-publishing house based in India. Your job is to write personalised royalty summary emails to BookLeaf authors.

BOOKLEAF COMMUNICATION TONE:
- Warm, personal, and encouraging — authors are creative partners, not just clients
- Professional but not corporate or cold
- Use "we" and "our team" when referring to BookLeaf
- Celebrate milestones (good sales numbers, fully paid royalties)
- Be empathetic and transparent about pending amounts
- Avoid jargon — write as if speaking to a creative person, not an accountant
- Signature should be from "The BookLeaf Team"

ROYALTY PAYOUT POLICY (include where relevant):
- BookLeaf processes royalty payouts quarterly: Q1 (Jan-Mar), Q2 (Apr-Jun), Q3 (Jul-Sep), Q4 (Oct-Dec)
- Payouts are processed within 45 days after each quarter closes
- Minimum payout threshold: ₹500
- If royalty_pending > 0 and last payout was within 90 days, it is within normal cycle
- If royalty_pending > 0 and last payout was over 90 days ago (or never), it may be overdue

IMPORTANT RULES:
- Do NOT include any placeholder text like [Author Name] or [Date]
- Do NOT use generic filler phrases like "I hope this email finds you well"
- DO use the actual numbers and dates from the data
- DO personalise based on their specific books and situation
- The email should be 250-400 words
- Format with clear sections using line breaks (not HTML)
- Start with "Subject:" on line 1, then a blank line, then the email body`;

const userPrompt = `Write a royalty summary email for the following BookLeaf author:

AUTHOR DETAILS:
- Name: ${a.name}
- City: ${a.city || 'India'}

CONSOLIDATED ROYALTY SUMMARY:
- Total royalty earned (all books): ${fmt(s.total_earned)}
- Total paid to date: ${fmt(s.total_paid)}
- Total pending: ${fmt(s.total_pending)}
- Overall payout status: ${s.overall_status}
- Next expected payout window: ${s.next_payout_quarter}

PUBLISHED BOOKS (${d.published_books.length} book${d.published_books.length !== 1 ? 's' : ''}):
${bookDetails || 'None'}
${d.production_books.length > 0 ? `
BOOKS IN PRODUCTION (${d.production_books.length}):
${productionDetails}` : ''}

INSTRUCTIONS:
- If ${s.total_pending} === 0: Celebrate that all royalties are fully paid up. Acknowledge their sales performance.
- If ${s.total_pending} > 0 and status is "Pending": Explain the pending amount is within normal quarterly cycle and when they can expect it.
- If ${s.total_pending} > 0 and status is "Overdue": Apologise for the delay, assure them the team is processing it, give next steps.
- If there are books in production: Give a brief, encouraging status update.
- Always close warmly from "The BookLeaf Team".`;

return [{
  json: {
    ...d,
    system_prompt: systemPrompt,
    user_prompt: userPrompt
  }
}];

// ─── EXTRACT & FORMAT AI OUTPUT ──────────────────────────────────
const aiResponse = $json;
const rawContent = aiResponse.choices?.[0]?.message?.content || '';

// Extract subject line and body
const lines = rawContent.split('\n');
let subject = 'Your BookLeaf Royalty Summary';
let body = rawContent;

if (lines[0].startsWith('Subject:')) {
  subject = lines[0].replace('Subject:', '').trim();
  body = lines.slice(2).join('\n').trim(); // skip subject + blank line
}

// Pass along the preceding node data
const prevData = $('Build AI Prompt').item.json;

return [{
  json: {
    author_id: prevData.author.id,
    author_name: prevData.author.name,
    author_email: prevData.author.email,
    email_subject: subject,
    email_body: body,
    log_id: prevData.log_id,
    bubble_base_url: prevData.bubble_base_url,
    bubble_api_key: prevData.bubble_api_key,
    tokens_used: aiResponse.usage?.total_tokens || 0,
    generated_at: new Date().toISOString()
  }
}];

