// ─── ERROR AGGREGATOR ────────────────────────────────────────────
// Determine which node failed and build structured error payload
const stage = $json.error ? $json.error.node || 'Unknown' : 'Unknown';
const message = $json.error?.message || $json.message || 'An unexpected error occurred';

const prevData = $('Validate & Extract Input').item.json || {};

return [{
  json: {
    author_id: prevData.author_id || 'unknown',
    log_id: prevData.log_id || null,
    bubble_base_url: prevData.bubble_base_url || '',
    bubble_api_key: prevData.bubble_api_key || '',
    error_stage: stage,
    error_message: message,
    failed_at: new Date().toISOString()
  }
}];

